import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import tseslint from 'typescript-eslint'
import { defineConfig, globalIgnores } from 'eslint/config'

export default defineConfig([
  // dist is build output; *.gql.ts and schema.types.ts are graphql-codegen
  // output (regenerated by bin/codegen) - linting generated code is noise.
  globalIgnores(['dist', 'src/**/*.gql.ts', 'src/graphql/schema.types.ts']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      js.configs.recommended,
      tseslint.configs.recommended,
      reactHooks.configs.flat.recommended,
      reactRefresh.configs.vite,
    ],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    rules: {
      // Fast refresh is a dev-time ergonomic, not correctness - a file exporting a component
      // plus its hook/constant just makes HMR remount a bit wider. Kept visible as a warning
      // so new splits are easy, but it doesn't fail the lint run
      'react-refresh/only-export-components': 'warn',
    },
  },
  {
    // Vendored shadcn primitives export their cva variants next to the component by upstream
    // convention - splitting them means re-doing it on every component update
    files: ['src/components/ui/**'],
    rules: {
      'react-refresh/only-export-components': 'off',
    },
  },
])
